    cluster.readAttributeApplicationVersion(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeApplication(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeApplication(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAttributeList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAttributeList(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeClusterRevision(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeClusterRevision(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFeatureMap(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFeatureMap(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeGeneratedCommandList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeGeneratedCommandList(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeProductID(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeProductID(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeStatus(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeStatus(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeVendorID(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeVendorID(completionHandler: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeVendorName(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeVendorName(completionHandler: { _, err in mtrExpectInvalidState(err) })
}

